package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import app.layan.quran.*;import java.io.*;
/** Actual inset bubble preview; preserves the native page background around the footer. */
public final class QiraatBubblePreview extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private View visible(View v,int id){Rect r=new Rect();if(v.getId()==id&&v.getGlobalVisibleRect(r)&&r.width()>v.getWidth()/2)return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=visible(((ViewGroup)v).getChildAt(i),id);if(found!=null)return found;}return null;}
 private void show(boolean night,int page)throws Exception{
  android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putBoolean("nightMode",night).putBoolean("useArabicNames",true).commit();
  QiraatReaderActivity a=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah","ibn-wardan").putExtra("page",page).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long end=SystemClock.elapsedRealtime()+120000;boolean ready=false;
  while(SystemClock.elapsedRealtime()<end){boolean[] r={false};runOnMainSync(()->r[0]=a.currentPageReady());if(r[0]){ready=true;break;}SystemClock.sleep(100);}if(!ready)throw new AssertionError("Source page not ready");waitForIdleSync();SystemClock.sleep(500);
  runOnMainSync(()->{View root=a.getWindow().getDecorView(),bubble=visible(root,QiraatGuide.PANEL),number=visible(root,QiraatReaderActivity.PAGE_NUMBER);if(bubble==null||number==null)throw new AssertionError("Bubble and number missing");Rect b=new Rect(),n=new Rect(),p=new Rect();bubble.getGlobalVisibleRect(b);number.getGlobalVisibleRect(n);((View)bubble.getParent()).getGlobalVisibleRect(p);int inset=Math.round(22*a.getResources().getDisplayMetrics().density);if(b.left-p.left<inset||p.right-b.right<inset||n.top<b.bottom)throw new AssertionError("Page edges or number overlap");if(bubble.getElevation()<=0||!bubble.getClipToOutline())throw new AssertionError("Rounded bubble styling absent");View nativePage=findNative(root);Rect nativeBounds=new Rect();nativePage.getGlobalVisibleRect(nativeBounds);if(nativeBounds.bottom<n.bottom||nativePage.getHeight()!=((View)bubble.getParent()).getHeight())throw new AssertionError("Native 3D page ends before footer");app.layan.quran.view.QuranImagePageLayout q=(app.layan.quran.view.QuranImagePageLayout)nativePage;Rect textBounds=new Rect();q.getImageView().getGlobalVisibleRect(textBounds);if(textBounds.bottom>b.top)throw new AssertionError("Text viewport overlaps bubble");});
  Bitmap image=NativeScreens.capture(this,a);File dir=a.getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"bubble-"+(night?"night":"day")+"-"+page+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();runOnMainSync(a::finish);waitForIdleSync();
 }
 private View findNative(View v){if(v instanceof app.layan.quran.view.QuranImagePageLayout){Rect r=new Rect();if(v.getGlobalVisibleRect(r)&&r.width()>v.getWidth()/2)return v;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View q=findNative(((ViewGroup)v).getChildAt(i));if(q!=null)return q;}return null;}
 public void onStart(){Bundle b=new Bundle();try{show(false,49);show(false,50);show(true,49);show(true,50);b.putString("result","PASS actual day/night rounded bubble, 22dp clear native page edges and page number below; original source page rendered");finish(Activity.RESULT_OK,b);}catch(Throwable e){b.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,b);}}
}
